import {goTo, outcome, Outcome} from 'play';

const sleep = (ms: number): Promise<void> => new Promise(resolve => setTimeout(resolve, ms));

export default async function main() {
  let trip: Outcome<unknown> = await goTo('sol_belt');
  let attempt = 0;
  while (trip.status === 'failed') {
    if (attempt >= 5) break;          // 6 attempts in all (the first + 5 retries)
    await sleep(1000 * 2 ** attempt); // 1s, 2s, 4s, 8s, 16s
    attempt += 1;
    trip = await goTo('sol_belt');
  }
  return trip;
}
```

Explanation of the design:

- **`goTo('sol_belt')`** is called once first, then retried. A `refused` status (or `done`/`partial`) fails the `=== 'failed'` test, so the loop body never runs for them and that Outcome is returned at once — a refused trip is not retried.
- **Backoff:** before each retry the program sleeps `1000 * 2**attempt` ms with `attempt` starting at 0, giving 1s, 2s, 4s, 8s, 16s.
- **At most 5 retries:** the `if (attempt >= 5) break;` guard runs after 5 failed attempts (6 total), returning the last Outcome.
- `trip` is annotated `Outcome<unknown>` because it is reassigned across calls of the same function; the literal return of `trip` satisfies the last-Outcome requirement.

(One note: the docs list only the top-level `setTimeout`-style delay as a static-refusal concern for `while(true)` without `stopped()`, but here the loop is bounded to 6 iterations and never a `while(true)`, so it passes the static gate.)

