A lone requirement: `disengage()` must run at the end no matter what the hunt does. So the whole thing is a try/finally around `hunt`, with `disengage()` in the `finally` and the hunt's Outcome (or a fallback) returned.

```ts
import {orient, goTo, hunt, disengage, outcome} from 'play';

export default async function main() {
  // The rendezvous: docked at a base when we left, so we can return and recover afterwards.
  const start = await orient();
  const dock = start.detail.present.location.docked_at ?? null;

  // 1) Get there. A refusal or a short tank on the way means the hunt will have nothing to do.
  let there: Outcome<unknown>;
  try {
    there = await goTo('sol_nebula');
  } catch (e) {
    return outcome(`goTo sol_nebula threw: ${String(e)}`, 'failed');
  }
  if (there.status !== 'done') return there;

  // 2) The hunt. try/finally so disengage() runs after it whether it ends, is refused,
  //    fails, or throws — a move sent mid-battle is what loses a ship.
  let res: Outcome<unknown>;
  try {
    res = await hunt({fights: 2});
  } catch (e) {
    res = outcome(`hunt threw: ${String(e)}`, 'failed');
  } finally {
    await disengage();   // guaranteed, after the hunt in every case
  }

  // 3) Come home and recover the take. This is best-effort: if it throws we still return
  //    the hunt Outcome rather than letting a recovery slip override it.
  if (dock) {
    try {
      const home = await goTo(dock);
      if (home.status === 'done') {
        const stow = await stow(res.gained.items);
        if (stow.status === 'done') return service();
        return stow;
      }
    } catch {
      /* the ship is home-ward; do not let recovery hide the hunt result */
    }
  }
  return res;
}
