import {orient, goTo, Outcome} from 'play';

export default async function main() {
  const present = await orient();

  // Exponential backoff, capped at 5 retries (6 attempts). Only `failed` (a transient
  // failure) is retried; any other status returns at once.
  const MAX_RETRIES = 5;
  let last: Outcome<unknown> = await goTo('sol_belt');

  if (last.status === 'failed') {
    let delayMs = 1000;
    for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
      await new Promise(resolve => setTimeout(resolve, delayMs));
      last = await goTo('sol_belt');
      if (last.status !== 'failed') break;      // done, refused, or partial: stop here
      delayMs *= 2;                             // 1s, 2s, 4s, 8s, 16s
    }
  }

  return last;
}
```

Key points:
- `let last: Outcome<unknown>` — the shared variable across calls is typed `Outcome<unknown>` (the rules warn that reassigning an `Outcome` of one type to another is a type error); the single file body can't recover `refused` vs `done` from `Outcome<unknown>` beyond `.status`, which is exactly what the task needs.
- The backoff loop waits 1s → 2s → 4s → 8s → 16s (×2 each retry) before up to 5 retries, breaking the moment a non-`failed` status comes back — so a `refused`, `done`, or `partial` trip is returned at once, never retried.
- Returns the last `goTo` Outcome, as required.

