export default async function main() {
  const board = await missions();

  // Free slots: how many missions we may hold. Read from the live board when it is there.
  const detail = board.detail as unknown as Record<string, unknown> | undefined;
  const cap = typeof detail?.['free_slots'] === 'number' ? (detail['free_slots'] as number)
    : typeof detail?.['capacity'] === 'number' ? (detail['capacity'] as number)
    : null;

  const rows = (board.detail as any)?.listings ?? (board.detail as any)?.missions ?? [];
  const eligible = rows
    .filter(m => typeof m?.reward === 'number' && m.reward >= 100 && m?.id)
    .sort((a: any, b: any) => (b.reward ?? 0) - (a.reward ?? 0));

  let accepted = 0;
  for (const m of eligible) {
    if (cap !== null && accepted >= cap) break;
    const res = await acceptMission(m.id);
    if (res.status !== 'done') {
      note(`stopped accepting at ${m.id}: ${res.why ?? res.status}`);
      break;
    }
    accepted++;
  }

  const done = await completeMissions();
  if (done.status !== 'done') note(`completeMissions: ${done.why ?? done.status}`);

  return outcome(
    `accepted ${accepted} board mission(s) of reward >= 100`,
    'done',
    {accepted}
  );
}
