  if (board.status === 'refused') return board; // nothing to list here; stop

  const listings = board.detail?.listings ?? [];

  // Board slots here: the ones with no mission attached, sorted cheapest-first.
  const free = listings
    .filter((m) => m.status === 'open' || m.status === 'available')
    .sort((a, b) => (a.reward ?? 0) - (b.reward ?? 0));

  let accepted = 0;
  for (const m of free) {
    if ((m.reward ?? 0) < 100) continue; // only accept rewards of at least 100

    // Do not fill beyond the slots the board will allow.
    const openNow = (account().missions ?? []).filter((a) => a.status !== 'complete').length;
    if (openNow >= free.length) break; // hold is full; no room for another

    const res = await acceptMission(m.id);
    if (res.status !== 'done') {
      note(`stopped accepting at ${m.id}: ${res.why ?? 'not done'}`);
      break; // first non-done accept halts the accepting
