```ts
import {
  orient,
  goTo,
  gatherUntil,
  sell,
  service,
  completeMissions,
  note,
  outcome,
} from 'play';
import type { Outcome } from 'play';

export default async function main() {
  // The service Outcome is what we return on the happy path. We capture it in a
  // deliberately-widened slot so a mid-run throw cannot break the type, and the
  // guaranteed credit note runs *after* this try/catch block, so it happens even
  // if a step above throws.
  let serviceOutcome: Outcome<unknown> | undefined;

  try {
    // We are docked at kepler_station; make sure of it, and stop if we cannot.
    const move = await goTo('kepler_station');
    if (move.status !== 'done') return move;

    // One mining trip to kepler_belt, returning home to kepler_station.
    const trip = await gatherUntil({ poi: 'kepler_belt', base: 'kepler_station' });
    if (trip.status !== 'done') return trip;

    // The trip stows at the base, so the take is in the store; sell the copper_ore
    // it settled, from the store, by name. (A sell of a row you do not hold is
    // `done` — nothing to sell — so this is safe to call unconditionally, but we
    // filter so `did` names exactly the copper.)
    const copper = (trip.detail.settled ?? []).filter((r) => r.item_id === 'copper_ore');
    if (copper.length) {
      await sell(copper, { from: 'store' });
    }

    // Bring the ship up: full tank, full hull at the counter we are docked at.
    serviceOutcome = await service();

    // Turn in anything completable. A not-done result here is fine; we just call it.
    await completeMissions();
  } catch {
    // Even if a step throws, we fall through to the guaranteed credit note below.
    // serviceOutcome may be undefined here; handled at the return.
  }

  // The last thing the program does, whatever happens: note our current credits,
  // read from orient() so the number is live.
  const look = await orient();
  await note(`credits: ${look.now?.credits ?? 0}`);

  // Return the service Outcome (or, if service never ran, a failed outcome that
  // at least carries the state of the world after the final orient).
  return serviceOutcome ?? outcome('mining trip aborted before service ran', 'failed', look.detail);
}
